items.frag:
#version 300 es
precision highp float;
uniform sampler2D u_input;
uniform float u_amount;
in vec2 v_texCoord;
out vec4 fragColor;
void main(){ vec4 c = texture(u_input, v_texCoord); fragColor = vec4(mix(c.rgb, vec3(1.0)-c.rgb, u_amount), c.a); }

#version 300 es
precision highp float;
uniform sampler2D u_outgoing;
uniform sampler2D u_incoming;
uniform float u_progress;
in vec2 v_texCoord;
out vec4 fragColor;
void main(){ fragColor = mix(texture(u_outgoing, v_texCoord), texture(u_incoming, v_texCoord), u_progress); }
